version 21.4R3-S2;
system {
    host-name SRX345-DC-GATEWAY;
    domain-name datacenter.corp;
    root-authentication {
        encrypted-password "$6$kO88$X98.aJ8qL4m19wK04ZqmKxQvC7wA21.hE"; ## SECRET-DATA
    }
    login {
        message "=====================================================\nRESTRICTED GATEWAY - AUTHORIZED IT AUDIT ACCESS ONLY\n=====================================================";
        idle-timeout 10;
        password {
            format sha-512;
            minimum-password-length 14;
        }
        class network-admin {
            permissions all;
        }
    }
    services {
        ssh {
            protocol-version v2;
            max-sessions-per-connection 4;
            connection-limit 10;
            rate-limit 3;
        }
        web-management {
            https {
                port 443;
                tls-version tlsv1.2;
                pki-local-certificate dc-cert;
            }
        }
    }
    syslog {
        host 192.168.10.25 {
            any notice;
            authorization info;
        }
    }
    ntp {
        server 192.168.10.1;
        server 192.168.10.2;
    }
}
snmp {
    v3 {
        usm {
            local-engine {
                user secops {
                    authentication-sha {
                        authentication-key "$9$9wK04ZqmKxQ";
                    }
                    privacy-aes128 {
                        privacy-key "$9$9wK04ZqmKxQpriv";
                    }
                }
            }
        }
    }
}
firewall {
    family inet {
        filter EDGE-MGMT-PROTECT {
            term ALLOW-SSH {
                from {
                    source-address {
                        192.168.0.0/16;
                    }
                    protocol tcp;
                    destination-port 22;
                }
                then accept;
            }
            term DROP-ALL {
                then {
                    count drop-counter;
                    discard;
                }
            }
        }
    }
}

